<?php
require 'includes/db.php';if(empty($_SESSION['cart']))redirect('cart.php');
function checkoutItems(mysqli $conn):array{$ids=array_keys($_SESSION['cart']??[]);if(!$ids)return [[],0];$in=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT * FROM products WHERE id IN ($in)");$s->bind_param($types,...$ids);$s->execute();$r=stmt_result($s);$items=[];$total=0;while($p=$r->fetch_assoc()){$p['qty']=max(1,(int)($_SESSION['cart'][$p['id']]??1));$items[]=$p;$total+=(float)$p['price']*$p['qty'];}return [$items,$total];}
[$items,$total]=checkoutItems($conn);if(!$items)redirect('cart.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(empty($_SESSION['user_id'])){flash('warning','Please log in before placing your order.');redirect('login.php');}$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(text_length($name)<2||text_length($name)>100||!preg_match('/^[0-9+()\s-]{7,25}$/',$phone)||text_length($address)<10||text_length($address)>1500){$error='Please enter a valid name, phone number and full delivery address.';}else{$conn->begin_transaction();try{$total=0;foreach($items as $p){$lock=$conn->prepare('SELECT price,stock FROM products WHERE id=? FOR UPDATE');$lock->bind_param('i',$p['id']);$lock->execute();$fresh=stmt_result($lock)->fetch_assoc();if(!$fresh||(int)$fresh['stock']<(int)$p['qty'])throw new RuntimeException('Stock for '.($p['name']??'an item').' has changed. Please update your bag.');$total+=(float)$fresh['price']*(int)$p['qty'];}$uid=(int)$_SESSION['user_id'];$s=$conn->prepare("INSERT INTO orders(user_id,customer_name,phone,address,total,status) VALUES(?,?,?,?,?,'Pending')");$s->bind_param('isssd',$uid,$name,$phone,$address,$total);if(!$s->execute())throw new RuntimeException('Could not save your order.');$oid=$s->insert_id;foreach($items as $p){$q=(int)$p['qty'];$price=(float)$p['price'];$x=$conn->prepare('INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)');$x->bind_param('iiid',$oid,$p['id'],$q,$price);if(!$x->execute())throw new RuntimeException('Could not save order items.');$u=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$u->bind_param('iii',$q,$p['id'],$q);if(!$u->execute()||$u->affected_rows!==1)throw new RuntimeException('Stock changed while ordering. Please retry.');}$conn->commit();unset($_SESSION['cart']);redirect('order-success.php?id='.$oid);}catch(Throwable $ex){$conn->rollback();$error=$ex->getMessage();}}}
$pageTitle='Secure Checkout | J.K BAGS';require 'includes/header.php';?>
<section class="form-page"><div class="form-box wide"><p class="eyebrow">ALMOST YOURS</p><h1>Complete Your Order</h1><p class="text-muted">Review your delivery details before placing the order.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(empty($_SESSION['user_id'])):?><div class="alert alert-warning">Please <a href="login.php">log in</a> before ordering. New here? <a href="register.php">Create an account</a>.</div><?php endif;?><div class="order-card"><strong>Order summary</strong><?php foreach($items as $p):?><div class="d-flex justify-content-between gap-3 mt-2"><span><?=e($p['name'])?> × <?=$p['qty']?></span><span><?=money($p['price']*$p['qty'])?></span></div><?php endforeach;?><hr><div class="d-flex justify-content-between"><strong>Total</strong><strong><?=money($total)?></strong></div></div><form method="post"><?=csrf_field()?><input name="name" maxlength="100" value="<?=e($_POST['name']??($_SESSION['user_name']??''))?>" placeholder="Full name" required><input name="phone" maxlength="25" value="<?=e($_POST['phone']??'')?>" placeholder="Phone number" required><textarea name="address" rows="4" maxlength="1500" placeholder="Complete delivery address" required><?=e($_POST['address']??'')?></textarea><button class="btn-gold" type="submit" <?=empty($_SESSION['user_id'])?'disabled':''?>>PLACE ORDER — <?=money($total)?></button></form><p class="small text-muted">Demo checkout records an order request; online payment is not collected.</p></div></section><?php require 'includes/footer.php';?>
